","import React, { useState, useEffect, useRef } from 'react';
import './PulseScoreHero.css';

const factors = [
  { key: 'complaints', label: 'Complaints', ok: true, score: 98 },
  { key: 'sla', label: 'SLA', ok: true, score: 96 },
  { key: 'equipment', label: 'Equipment', ok: true, score: 92 },
  { key: 'fraud', label: 'Refund Fraud', ok: true, score: 94 },
  { key: 'partner', label: 'Partner Incidents', ok: true, score: 88 },
];

export function PulseScoreHero() {
  const targetScore = 87;
  const [displayScore, setDisplayScore] = useState(0);
  const [score, setScore] = useState(targetScore);
  const [animating, setAnimating] = useState(false);
  const hasAnimated = useRef(false);

  // Count-up animation on initial load
  useEffect(() => {
    if (hasAnimated.current) return;
    hasAnimated.current = true;

    const duration = 1800;
    const startTime = Date.now();

    const animate = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);
      // Ease-out cubic for smooth deceleration
      const eased = 1 - Math.pow(1 - progress, 3);
      const current = Math.round(eased * targetScore);
      setDisplayScore(current);

      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        setDisplayScore(targetScore);
      }
    };

    // Small delay before starting animation
    const timeout = setTimeout(() => requestAnimationFrame(animate), 400);
    return () => clearTimeout(timeout);
  }, []);

  // Live fluctuation after initial animation
  useEffect(() => {
    const interval = setInterval(() => {
      const delta = Math.random() > 0.5 ? 1 : -1;
      setScore((s) => {
        const newScore = Math.max(60, Math.min(99, s + delta));
        setDisplayScore(newScore);
        return newScore;
      });
      setAnimating(true);
      setTimeout(() => setAnimating(false), 600);
    }, 8000);
    return () => clearInterval(interval);
  }, []);

  const status = displayScore >= 80 ? 'healthy' : displayScore >= 60 ? 'warning' : 'critical';
  const statusLabel = displayScore >= 80 ? 'HEALTHY' : displayScore >= 60 ? 'WARNING' : 'CRITICAL';

  return (
    <div className={`pulse-hero pulse-hero--${status}`}>
      <div className="pulse-hero__main">
        <div className="pulse-hero__ring-container">
          <svg viewBox="0 0 120 120" className="pulse-hero__ring">
            <circle cx="60" cy="60" r="52" className="pulse-hero__ring-bg" />
            <circle cx="60" cy="60" r="52" className="pulse-hero__ring-fill"
              strokeDasharray={`${(displayScore / 100) * 327}, 327`} />
          </svg>
          <div className={`pulse-hero__score ${animating ? 'pulse-hero__score--animate' : ''}`}>
            <span className="pulse-hero__number">{displayScore}</span>
          </div>
        </div>
        <div className="pulse-hero__info">
          <div className="pulse-hero__label">PulseScore™</div>
          <div className="pulse-hero__sublabel">Composite Health Index</div>
          <div className="pulse-hero__badges-row">
            <div className={`pulse-hero__badge pulse-hero__badge--${status}`}>
              <span className="pulse-hero__badge-dot" />
              {statusLabel}
            </div>
            <div className="pulse-hero__change">
              <span className="pulse-hero__change-arrow">↑</span>
              <span className="pulse-hero__change-value">+5 Today</span>
            </div>
          </div>
        </div>
      </div>
      <div className="pulse-hero__breakdown">
        <div className="pulse-hero__breakdown-title">Health Factors</div>
        <div className="pulse-hero__factors">
          {factors.map((f) => (
            <div key={f.key} className={`pulse-hero__factor ${f.ok ? 'pulse-hero__factor--ok' : 'pulse-hero__factor--fail'}`}>
              <span className="pulse-hero__factor-check">{f.ok ? '✓' : '✗'}</span>
              <span className="pulse-hero__factor-label">{f.label}</span>
              <span className="pulse-hero__factor-score">{f.score}%</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
