","import React from 'react';
import './StoreHealth.css';

interface Store {
  id: string;
  name: string;
  score: number;
  status: 'green' | 'warning' | 'critical';
  orders: number;
  complaints: number;
  downtime: string;
}

const stores: Store[] = [
  { id: '112', name: 'Banjara Hills', score: 94, status: 'green', orders: 1842, complaints: 3, downtime: '0m' },
  { id: '108', name: 'Jubilee Hills', score: 78, status: 'green', orders: 1456, complaints: 8, downtime: '4m' },
  { id: '115', name: 'Gachibowli', score: 62, status: 'warning', orders: 1203, complaints: 14, downtime: '12m' },
  { id: '103', name: 'Madhapur', score: 45, status: 'warning', orders: 987, complaints: 22, downtime: '28m' },
  { id: '121', name: 'Kondapur', score: 28, status: 'critical', orders: 654, complaints: 38, downtime: '47m' },
  { id: '109', name: 'Hitech City', score: 91, status: 'green', orders: 2105, complaints: 2, downtime: '0m' },
];

function barColor(status: string) {
  if (status === 'green') return 'var(--cc-accent)';
  if (status === 'warning') return 'var(--cc-warning)';
  return 'var(--cc-critical)';
}

function handleStoreClick(store: Store) {
  // Navigate to Store Intelligence dashboard
  const url = `x_2145749_qc_store_intel.do?store_id=${store.id}&store_name=${encodeURIComponent(store.name)}`;
  window.location.href = url;
}

export function StoreHealth() {
  return (
    <div className="card store-health">
      <h2 className="section-title">Store Health Grid</h2>
      <div className="store-health__grid">
        {stores.map((s) => (
          <div
            key={s.name}
            className={`store-health__item store-health__item--${s.status} store-health__item--clickable`}
            onClick={() => handleStoreClick(s)}
            title={`Open Store ${s.id} — ${s.name} Intelligence`}
          >
            <div className="store-health__top-row">
              <div className="store-health__name">
                <span className="store-health__store-id">#{s.id}</span>
                {s.name}
              </div>
              <div className="store-health__score" style={{ color: barColor(s.status) }}>
                {s.score}
              </div>
            </div>
            <div className="store-health__bar-track">
              <div className="store-health__bar-fill"
                style={{ width: `${s.score}%`, background: barColor(s.status) }} />
            </div>
            <div className="store-health__metrics-header">
              <span className="store-health__metric-header">Orders</span>
              <span className="store-health__metric-header">Complaints</span>
              <span className="store-health__metric-header">Downtime</span>
            </div>
            <div className="store-health__metrics">
              <span className="store-health__metric">📦 {s.orders.toLocaleString()}</span>
              <span className="store-health__metric">📋 {s.complaints}</span>
              <span className="store-health__metric">⏱ {s.downtime}</span>
            </div>
            <div className="store-health__drilldown">
              <span className="store-health__drilldown-text">View Details →</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
