","import React from 'react';
import './CityHeatmap.css';

interface MapArea {
  name: string;
  stores: { id: number; status: 'green' | 'warning' | 'critical' }[];
}

const areas: MapArea[] = [
  { name: 'Banjara Hills', stores: [{ id: 101, status: 'green' }, { id: 102, status: 'green' }, { id: 103, status: 'green' }, { id: 104, status: 'green' }] },
  { name: 'Jubilee Hills', stores: [{ id: 111, status: 'green' }, { id: 112, status: 'critical' }, { id: 113, status: 'green' }, { id: 114, status: 'green' }] },
  { name: 'Gachibowli', stores: [{ id: 121, status: 'warning' }, { id: 122, status: 'green' }, { id: 123, status: 'warning' }, { id: 124, status: 'green' }] },
  { name: 'Madhapur', stores: [{ id: 131, status: 'warning' }, { id: 132, status: 'warning' }, { id: 133, status: 'critical' }, { id: 134, status: 'green' }] },
  { name: 'Kondapur', stores: [{ id: 141, status: 'critical' }, { id: 142, status: 'warning' }, { id: 143, status: 'warning' }, { id: 144, status: 'green' }] },
  { name: 'Hitech City', stores: [{ id: 151, status: 'green' }, { id: 152, status: 'green' }, { id: 153, status: 'green' }, { id: 154, status: 'warning' }] },
];

const statusColors: Record<string, string> = {
  green: 'var(--cc-accent)',
  warning: 'var(--cc-warning)',
  critical: 'var(--cc-critical)',
};

export function CityHeatmap() {
  const totalStores = areas.reduce((acc, a) => acc + a.stores.length, 0);
  const healthyStores = areas.reduce((acc, a) => acc + a.stores.filter(s => s.status === 'green').length, 0);
  const criticalStores = areas.reduce((acc, a) => acc + a.stores.filter(s => s.status === 'critical').length, 0);

  return (
    <div className="card city-heatmap">
      <div className="city-heatmap__header">
        <h2 className="section-title">Store Map — Hyderabad</h2>
        <div className="city-heatmap__legend">
          <span className="city-heatmap__legend-item"><span className="city-heatmap__legend-dot" style={{ background: 'var(--cc-accent)' }} />Healthy</span>
          <span className="city-heatmap__legend-item"><span className="city-heatmap__legend-dot" style={{ background: 'var(--cc-warning)' }} />Warning</span>
          <span className="city-heatmap__legend-item"><span className="city-heatmap__legend-dot" style={{ background: 'var(--cc-critical)' }} />Critical</span>
        </div>
      </div>
      <div className="city-heatmap__stats">
        <span className="city-heatmap__stat">{totalStores} Total</span>
        <span className="city-heatmap__stat city-heatmap__stat--green">{healthyStores} Healthy</span>
        <span className="city-heatmap__stat city-heatmap__stat--red">{criticalStores} Critical</span>
      </div>
      <div className="city-heatmap__grid">
        {areas.map((area) => (
          <div key={area.name} className="city-heatmap__row">
            <span className="city-heatmap__name">{area.name}</span>
            <div className="city-heatmap__dots">
              {area.stores.map((s) => (
                <span key={s.id} className={`city-heatmap__dot city-heatmap__dot--${s.status}`}
                  style={{ background: statusColors[s.status] }}
                  title={`Store ${s.id}`} />
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
